     1	/** The insured things the MHPCO knows, and the price-list facts that both the
     2	 *  premium office and the claims office read off the same catalogue entry.
     3	 *  Neither side owns this knowledge: a new item type is one catalogue change,
     4	 *  not a change to how premiums or payouts are decided. */
     5	
     6	export interface Item {
     7	  type: string;
     8	  material?: string;
     9	  enchantment?: number;
    10	  cursed?: boolean;
    11	}
    12	
    13	/** Every component -- rune, moonstone -- carries the same price-list base
    14	 *  premium, independent of which component it is. */
    15	const COMPONENT_BASE_PREMIUM = 25;
    16	
    17	/** MHPCO price list: base premium in G per item type. */
    18	const BASE_PREMIUMS: Record<string, number> = {
    19	  sword: 100,
    20	  amulet: 60,
    21	  staff: 80,
    22	  potion: 40,
    23	  rune: COMPONENT_BASE_PREMIUM,
