     1	/** The claims office: what the MHPCO pays out when an insured item is damaged.
     2	 *  Every decision here belongs to the claims handbook -- the deductible, the
     3	 *  special clauses, the cap on a policy -- and is revised independently of the
     4	 *  tariff that priced the policy. */
     5	
     6	import { type Item } from "./item-catalog.js";
     7	
     8	export interface Damage {
     9	  itemType: string;
    10	  amount: number;
    11	}
    12	
    13	export interface Incident {
    14	  cause: string;
    15	  damages: Damage[];
    16	}
    17	
    18	export interface Policy {
    19	  items: Item[];
    20	}
    21	
    22	export interface ClaimResult {
    23	  payout: number;
    24	  remainingCap: number;
    25	}
    26	
    27	const DEDUCTIBLE_PER_DAMAGE = 100;
    28	
    29	/** From enchantment level 8 upwards the handbook reimburses only half the
    30	 *  damage: powerful enchantments are held to attract their own misfortune. */
    31	const HIGH_ENCHANTMENT_CLAUSE_THRESHOLD = 8;
    32	const HIGH_ENCHANTMENT_CLAUSE_SHARE = 0.5;
    33	
    34	/** The MHPCO opens a policy over the items a quote covered. */
    35	export function createPolicy(items: Item[]): Policy {
    36	  return { items };
    37	}
    38	
    39	/** The MHPCO bears its deductible against a damage; it never turns the
    40	 *  deductible round into a charge the customer owes the office. A damage
    41	 *  smaller than the deductible is simply not reimbursed. */
    42	function neverACharge(reimbursement: number): number {
    43	  return Math.max(reimbursement, 0);
    44	}
    45	
    46	/** Whether the handbook's high-enchantment clause covers a damaged item. */
    47	function fallsUnderHighEnchantmentClause(item: Item): boolean {
    48	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_THRESHOLD;
    49	}
    50	
    51	/** The share of a damage the handbook's special clauses reimburse, before the
    52	 *  deductible is kept back. */
    53	function reimbursableAmount(damage: Damage, item: Item): number {
    54	  if (fallsUnderHighEnchantmentClause(item)) {
    55	    return damage.amount * HIGH_ENCHANTMENT_CLAUSE_SHARE;
    56	  }
    57	  return damage.amount;
    58	}
    59	
    60	/** The handbook's reimbursement decision for one damage event: the special
    61	 *  clauses decide the reimbursable amount, from which the MHPCO keeps back its
    62	 *  deductible. */
    63	function reimbursementForDamage(damage: Damage, item: Item): number {
    64	  return neverACharge(reimbursableAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
    65	}
    66	
    67	/** The insured item a reported damage refers to. */
    68	function damagedItem(policy: Policy, damage: Damage): Item {
    69	  return policy.items.filter((item) => item.type === damage.itemType)[0];
    70	}
    71	
    72	/** What the MHPCO settles for one incident against a policy: every reported
    73	 *  damage reimbursed under the handbook, added up. The cap the office keeps on
    74	 *  a policy is a separate decision it has not yet made, so the remaining cap is
    75	 *  reported as nothing held back. */
    76	export function claim(policy: Policy, incident: Incident): ClaimResult {
    77	  const payout = incident.damages.reduce(
    78	    (sum, damage) => sum + reimbursementForDamage(damage, damagedItem(policy, damage)),
    79	    0,
    80	  );
    81	  return { payout, remainingCap: 0 };
    82	}

